args.sql:
CREATE TABLE IF NOT EXISTS container_tss_monitoring (containregistry VARCHAR PRIMARY KEY, latest_tss NUMERIC, last_updated TIMESTAMP);
INSERT INTO container_tss_monitoring (containregistry, latest_tss, last_updated)
SELECT containlink, (1 - tempdevcount / 100.0) * (1 - critevents / 10.0) * tempstabidx, CURRENT_TIMESTAMP
FROM (SELECT DISTINCT ON (containlink) containlink, tempdevcount, critevents, tempstabidx FROM sensordata ORDER BY containlink, alerttime DESC NULLS LAST, sensortrack DESC) s
ON CONFLICT (containregistry) DO UPDATE SET latest_tss = EXCLUDED.latest_tss, last_updated = EXCLUDED.last_updated;

SELECT AVG(latest_tss) AS average_tss,
       COUNT(*) FILTER (WHERE latest_tss < 0.7) AS containers_below_0_7
FROM container_tss_monitoring;

